// 1. Install: npm install @next/bundle-analyzer

// 2. next.config.js
// We wrap the config in the analyzer. It only triggers if an env variable is set.
const withBundleAnalyzer = require('@next/bundle-analyzer')({
  enabled: process.env.ANALYZE === 'true',
})

module.exports = withBundleAnalyzer({
  // your standard next.js config here
})

// 3. Run the analysis in the terminal:
// ANALYZE=true npm run build

// Next.js will build the app and pop open a beautiful interactive HTML 
// treemap showing exactly which libraries are bloated!
